def main():
    items = []
    for (iid, title, cat, mood, orient, desc, tags, topics) in S:
        use, avoid = USE[cat]
        items.append(dict(id=iid, title=title, category=cat, mood=mood, desc=desc, tags=tags, topics=topics, orientation=orient, use_for=use, avoid_for=avoid))
    ids = [i["id"] for i in items]
    assert len(ids) == len(set(ids)), "duplicate ids"
    first = json.load(open(os.path.join(ROOT, "docs", "vector_catalog", "plan.json")))["items"]
    assert not (set(ids) & {i["id"] for i in first}), "id clashes with batch 1"
    json.dump(dict(plan_id="vector-catalog-2", approved_by="owner 2026-11-27 ('go for 150')", cap_usd=12.0, items=items), open(OUT, "w"), indent=1)
    tall = sum(1 for i in items if i["orientation"] == "tall")
    print(len(items), "scenes,", tall, "tall ->", OUT)


if __name__ == "__main__":
    main()
